    const bgt = v => v.n < 10 ? "—" : pc(v.frac_gt_5d) + bnote(v);
    const bpeak = v => v.n < 10 ? "—" : pc(v.at_peak_share) + " / " + pc(v.below_peak_share);
    const rowB = r => "<tr><td>" + r.rule + "</td>" + ["aug", "sep"].map(m => {
      const v = r[m];
      return "<td class='num'>" + v.n + "</td><td class='num " + cls(v.usd) + "'>" + money(v.usd) + "</td><td class='num " +
        (v.n >= 10 && v.frac_gt_5d > 0.10 ? "neg" : "") + "'>" + bgt(v) + "</td><td class='num muted'>" + bpeak(v) + "</td>";
    }).join("<td class='sep'></td>") + "</tr>";
    document.getElementById("approach-busy-rules").innerHTML =
      "<thead><tr><th>правило</th><th colspan='4'>август</th><th class='sep'></th><th colspan='4'>сентябрь</th></tr>" +
      "<tr><th></th><th class='num'>n</th><th class='num'>$</th><th class='num'>доля &gt; 5 сут</th><th class='num'>на пике / в просадке</th><th class='sep'></th>" +
      "<th class='num'>n</th><th class='num'>$</th><th class='num'>доля &gt; 5 сут</th><th class='num'>на пике / в просадке</th></tr></thead><tbody>" +
      B.rules_kpi.map(rowB).join("") + "</tbody>";
