    const rowLev = r => "<tr><td>" + r.rule + "</td>" + ["aug", "sep"].map(m => {
      const wd = [1, 2, 3].map(x => (r[m].worst_day_pct * x).toFixed(1).replace("-", "−") + "%").join(" / ");
