      "<tr><th></th><th class='num'>худшие сутки, % депо</th><th class='num'>просадка, % депо</th><th class='num'>стресс обвала</th><th class='sep'></th>" +
      "<th class='num'>худшие сутки, % депо</th><th class='num'>просадка, % депо</th><th class='num'>стресс обвала</th></tr></thead><tbody>" +
