// ---------- срезы по номеру подхода (владелец 27.09 через CEO: «детализируй по срезам») ----------
const SLICE_LABEL = {age: "возраст стены", size: "размер стены", gap: "время с прошлого подхода", outcome: "исход прошлого подхода",
  before45: "подходов до 45 мин", traded_serial: "номер среди торгуемых", btc: "глубина BTC", episode_minute: "минута эпизода", family: "семейство волатильности"};
function sliceCell(c) {
  if (!c || !c.n) return "<td class='cell thin'>—</td>";
  if (c.n < 10) return "<td class='cell thin'>мало <span class='muted'>(n=" + c.n + ")</span></td>";
  const pc = x => x == null ? "—" : Math.round(x * 100) + "%";
  return "<td class='cell'>n=" + c.n + "<br>" + moneyFine(c.usd_pt) + "/сд · " + pc(c.win) + "</td>";
}
function sliceHeat(fam, pk, title) {
  const table = fam.table[pk];
  const buckets = Object.keys(table);
  const allN = new Set();
  buckets.forEach(b => Object.keys(table[b]).forEach(n => { if (table[b][n].n) allN.add(n); }));
  const order = ["1", "2", "3", "4", "5", "6", "7+"].filter(n => allN.has(n));
  if (!order.length) return "";
  let h = "<div class='scroll'><h4 style='margin:0 0 6px;font:600 12.5px var(--font-body);color:var(--ink-2)'>" + title + "</h4><table class='heat-table'><thead><tr><th>подход &rarr;</th>" +
    order.map(n => "<th>" + n + "</th>").join("") + "</tr></thead><tbody>";
  for (const b of buckets) {
    h += "<tr><td>" + (b === "" ? "все" : b) + "</td>" + order.map(n => sliceCell(table[b][n])).join("") + "</tr>";
  }
  return h + "</tbody></table></div>";
}
function renderSlices() {
  const A = NH && NH.approach, S = A && A.slices;
  const swBox = document.getElementById("slices-switch"), tBox = document.getElementById("slices-tables");
  if (!S || !S.families) { if (swBox) swBox.innerHTML = ""; if (tBox) tBox.innerHTML = ""; return; }
  swBox.innerHTML = Object.keys(SLICE_LABEL).map(k => "<button data-slice='" + k + "' aria-pressed='" + (k === sliceKey) + "'>" + SLICE_LABEL[k] + "</button>").join("");
  swBox.querySelectorAll("button").forEach(b => b.addEventListener("click", () => { sliceKey = b.dataset.slice; renderSlices(); }));
  const ap = S.age_pooled;
  const frac2 = v => (v >= 0 ? "+" : "−") + Math.abs(v).toFixed(2).replace(".", ",");
  const bps0 = v => (v >= 0 ? "+" : "−") + Math.abs(Math.round(v));
  document.getElementById("slices-headline").innerHTML = "<b>Главное</b>: номер подхода внутри корзины возраста стены — август &Delta; доли в плюс " +
    frac2(ap.aug.pooled_win_diff_2plus_vs_1) + " / " + bps0(ap.aug.pooled_bps_diff_2plus_vs_1) + " bps, сентябрь " +
    frac2(ap.sep.pooled_win_diff_2plus_vs_1) + " / " + bps0(ap.sep.pooled_bps_diff_2plus_vs_1) + " bps — знак разный между месяцами, эффекта нет.";
  const fam = S.families[sliceKey];
  tBox.innerHTML = sliceHeat(fam, "aug", "Август") + sliceHeat(fam, "sep", "Сентябрь");
  document.getElementById("slices-note").textContent = S.n_cells + " клеток на тех же днях (" + fam.title + ") — карта-описание, не проверка; правило из любой клетки — только новым протоколом.";
}

