const wrap = document.querySelector('.wrap');
let culprits = [];
document.querySelectorAll('body *').forEach(el => {
  const r = el.getBoundingClientRect();
  if (r.width > 380 && el.children.length < 30) {
    culprits.push({tag: el.tagName, id: el.id, cls: el.className.toString().slice(0,60), w: Math.round(r.width)});
  }
});
// keep only the "leaf-most" wide ones: elements whose width is much bigger than 375 and are deep
culprits.sort((a,b)=>b.w-a.w);
JSON.stringify(culprits.slice(0,20))

